var offsets=new[]{new UnityEngine.Vector3Int(-1,1,0),new UnityEngine.Vector3Int(0,1,0),new UnityEngine.Vector3Int(1,1,0),new UnityEngine.Vector3Int(-1,0,0),new UnityEngine.Vector3Int(1,0,0),new UnityEngine.Vector3Int(-1,-1,0),new UnityEngine.Vector3Int(0,-1,0),new UnityEngine.Vector3Int(1,-1,0)};
int Bit(int x,int y){return Array.FindIndex(offsets,p=>p.x==x&&p.y==y);}int Canonical(int m){foreach(int i in new[]{0,2,5,7}){var p=offsets[i];if((m&(1<<Bit(p.x,0)))==0||(m&(1<<Bit(0,p.y)))==0)m&=~(1<<i);}return m;}
var root=new UnityEngine.GameObject("Autotile regression",typeof(UnityEngine.Grid));root.transform.position=new UnityEngine.Vector3(1000,1000,0);var child=new UnityEngine.GameObject("Tile probe",typeof(UnityEngine.Tilemaps.Tilemap));child.transform.SetParent(root.transform,false);var map=child.GetComponent<UnityEngine.Tilemaps.Tilemap>();
var itile=(UnityEngine.Tilemaps.ITilemap)Activator.CreateInstance(typeof(UnityEngine.Tilemaps.ITilemap),System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic,null,new object[]{map},null);
var reports=new System.Collections.Generic.List<object>();try{foreach(var name in new[]{"PathTile","Mountain"}){
var generated="Assets/Sprites/AniamtedTiles/"+name+"CompleteSprites.asset";UnityEditor.AssetDatabase.ImportAsset(generated,UnityEditor.ImportAssetOptions.ForceSynchronousImport|UnityEditor.ImportAssetOptions.ForceUpdate);
var sprites=UnityEditor.AssetDatabase.LoadAllAssetsAtPath(generated).OfType<UnityEngine.Sprite>().ToArray();if(sprites.Length!=47||sprites.Any(s=>s.vertices.Length<16||s.rect.width!=16||s.pixelsPerUnit!=16||s.uv.Any(uv=>uv.x<-.00001f||uv.x>1.00001f||uv.y<-.00001f||uv.y>1.00001f)))throw new System.Exception("Invalid persisted geometry "+name);
var tile=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.RuleTile>("Assets/Sprites/AniamtedTiles/"+name+".asset");int checkedCount=0;for(int mask=0;mask<256;mask++){map.ClearAllTiles();map.SetTile(UnityEngine.Vector3Int.zero,tile);for(int i=0;i<8;i++)if((mask&(1<<i))!=0)map.SetTile(offsets[i],tile);map.RefreshAllTiles();var matches=tile.m_TilingRules.Where(r=>{var matrix=UnityEngine.Matrix4x4.identity;return tile.RuleMatches(r,UnityEngine.Vector3Int.zero,itile,ref matrix);}).ToArray();if(matches.Length!=1||matches[0].m_Id!=Canonical(mask)||map.GetSprite(UnityEngine.Vector3Int.zero)!=matches[0].m_Sprites[0])throw new System.Exception("Incorrect or ambiguous state "+name+":"+mask);checkedCount++;}
map.ClearAllTiles();map.SetTile(UnityEngine.Vector3Int.zero,tile);var alone=map.GetSprite(UnityEngine.Vector3Int.zero);map.SetTile(UnityEngine.Vector3Int.right,tile);var connected=map.GetSprite(UnityEngine.Vector3Int.zero);map.SetTile(UnityEngine.Vector3Int.up,tile);var missingDiagonal=map.GetSprite(UnityEngine.Vector3Int.zero);map.SetTile(UnityEngine.Vector3Int.right+UnityEngine.Vector3Int.up,tile);var withDiagonal=map.GetSprite(UnityEngine.Vector3Int.zero);map.SetTile(UnityEngine.Vector3Int.right+UnityEngine.Vector3Int.up,null);if(alone==connected||missingDiagonal==withDiagonal||map.GetSprite(UnityEngine.Vector3Int.zero)!=missingDiagonal)throw new System.Exception("Neighbor repaint did not refresh "+name);
reports.Add(new{name,rules=tile.m_TilingRules.Count,savedSpriteStates=sprites.Length,neighborCombinations=checkedCount,uniqueRulePerCombination=true,repaintRefresh=true,persistedGeometry=true});
}}finally{UnityEngine.Object.DestroyImmediate(root);}var report=new{passed=true,playMode=UnityEditor.EditorApplication.isPlaying,tiles=reports};System.IO.File.WriteAllText("docs/design/autotile-final-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;